<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3'
import { ref } from 'vue'
defineProps<{result:{users?:any[];total?:number;next_token?:string|null};filters:Record<string,any>;error:string|null}>()
const search=ref('')
const loading=ref(false)
const apply=()=>{loading.value=true;router.get('/users',{search_term:search.value,from:0,limit:50},{preserveState:true,onFinish:()=>loading.value=false})}
const status=(u:any)=>u.deactivated?'غیرفعال':u.locked?'قفل‌شده':u.shadow_banned?'Shadow ban':'فعال'
</script>
<template><Head title="مدیریت کاربران"/><v-container fluid class="pa-6"><div class="d-flex align-center justify-space-between mb-5"><div><h1 class="text-h4">کاربران</h1><div class="text-medium-emphasis">مدیریت حساب‌های Matrix</div></div><v-btn color="primary" prepend-icon="mdi-refresh" @click="apply">به‌روزرسانی</v-btn></div><v-card rounded="xl" class="pa-4"><v-row align="center"><v-col cols="12" md="5"><v-text-field v-model="search" label="جستجو بر اساس شناسه یا نام" prepend-inner-icon="mdi-magnify" hide-details @keyup.enter="apply"/></v-col><v-col cols="12" md="3"><v-select label="وضعیت" :items="['همه','فعال','غیرفعال','قفل‌شده']" hide-details/></v-col><v-col cols="12" md="2"><v-btn block color="primary" @click="apply">جستجو</v-btn></v-col></v-row><v-alert v-if="error" type="error" variant="tonal" class="my-4">{{ error }}</v-alert><v-skeleton-loader v-if="loading" type="table-row@8"/><v-table v-else class="mt-4"><thead><tr><th>شناسه</th><th>نام نمایشی</th><th>وضعیت</th><th>مدیر</th><th></th></tr></thead><tbody><TransitionGroup name="row"><tr v-for="u in (result.users||[])" :key="u.name"><td class="font-weight-medium">{{ u.name }}</td><td>{{ u.displayname||'—' }}</td><td><v-chip size="small" :color="u.deactivated?'error':u.locked?'warning':'success'">{{ status(u) }}</v-chip></td><td>{{ u.admin?'بله':'خیر' }}</td><td><v-btn size="small" variant="tonal" :href="'/users/'+encodeURIComponent(u.name)">جزئیات</v-btn></td></tr></TransitionGroup><tr v-if="!(result.users||[]).length"><td colspan="5" class="text-center pa-8">کاربری یافت نشد.</td></tr></tbody></v-table><div class="text-caption text-medium-emphasis mt-3">تعداد کل: {{ result.total??0 }}</div></v-card></v-container></template>
<style scoped>.row-enter-active,.row-leave-active{transition:all .25s ease}.row-enter-from{opacity:0;transform:translateY(8px)}@media(prefers-reduced-motion:reduce){.row-enter-active,.row-leave-active{transition:none}}</style>
